import { build } from "esbuild";
import { JSDOM } from "jsdom";
import { readdir, readFile } from "node:fs/promises";
import assert from "node:assert/strict";

// Fixtures are generated by LimsWorkflowTest against SQLite :memory:, never production data.
const directory = process.argv[2] || "/private/tmp/tahlila-ui-tests";
const bundle = await build({
    entryPoints: ["resources/js/lims/main.jsx"],
    jsx: "automatic",
    bundle: true,
    write: false,
    format: "iife",
    loader: { ".css": "empty" },
    define: { "process.env.NODE_ENV": '"production"' },
});
let count = 0;
const pages = await Promise.all(
    (await readdir(directory))
        .filter((file) => file.endsWith(".json"))
        .map(async (file) =>
            JSON.parse(await readFile(`${directory}/${file}`, "utf8")),
        ),
);
const patientsPage = pages.find((page) => page.screen === "patients");
for (const page of pages) {
    const dom = new JSDOM(
        '<!doctype html><div id="lims"></div><script type="application/json" id="lims-data"></script>',
        {
            url: `http://localhost${page.path.replace(/^\/\//, "/")}`,
            runScripts: "outside-only",
            pretendToBeVisual: true,
        },
    );
    const errors = [];
    const requests = [];
    dom.window.addEventListener("error", (e) => errors.push(e.error));
    dom.window.scrollTo = () => {};
    dom.window.fetch = async (url) => {
        requests.push(String(url));
        if (String(url).startsWith("/api/lims/patients")) {
            return {
                ok: true,
                status: 200,
                headers: { get: () => "application/json" },
                json: async () => patientsPage,
            };
        }
        return {
            ok: false,
            status: 422,
            headers: { get: () => "application/json" },
            json: async () => ({ errors: {} }),
        };
    };
    dom.window.document.getElementById("lims-data").textContent =
        JSON.stringify(page);
    dom.window.eval(bundle.outputFiles[0].text);
    await new Promise((resolve) => setTimeout(resolve, 30));
    assert.equal(errors.length, 0, `${page.path}: ${errors.join(", ")}`);
    assert.ok(
        dom.window.document.querySelector("h1"),
        `${page.path}: missing heading`,
    );
    if (page.screen === "dashboard") {
        const root = dom.window.document.getElementById("lims");
        dom.window.document.querySelector('a[href="/patients"]').click();
        await new Promise((resolve) => setTimeout(resolve, 50));
        assert.equal(dom.window.location.pathname, "/patients");
        assert.equal(
            requests.at(-1),
            "/api/lims/patients",
            "React Router must load internal pages from the Laravel JSON API",
        );
        assert.equal(
            dom.window.document.getElementById("lims"),
            root,
            "SPA navigation must keep the original React document mounted",
        );
        assert.ok(
            dom.window.document
                .querySelector("h1")
                .textContent.includes("Patients"),
            "JSON page data was not rendered after client navigation",
        );
    }
    if (!page.screen.startsWith("auth.")) {
        assert.ok(
            dom.window.document.querySelector("nav"),
            `${page.path}: missing navigation`,
        );
        assert.equal(
            dom.window.document.querySelectorAll(".nav-section").length,
            3,
            `${page.path}: sidebar sections missing`,
        );
        assert.equal(
            dom.window.document.querySelector(".workspace"),
            null,
            `${page.path}: legacy workspace block is still rendered`,
        );
    }
    assert.ok(
        !dom.window.document.body.textContent.includes("[object Object]"),
        `${page.path}: invalid displayed value`,
    );
    if (page.screen === "order" && !page.record) {
        dom.window.document.querySelector(".catalogue button").click();
        await new Promise((resolve) => setTimeout(resolve, 15));
        const form = dom.window.document
            .querySelector(".order-layout")
            .closest("form");
        let data = new dom.window.FormData(form);
        assert.equal(data.get("tests[]"), "1*null*null");
        assert.equal(data.get("total_price"), "50.00");
        form.addEventListener("submit", (e) => e.preventDefault());
        form.dispatchEvent(
            new dom.window.Event("submit", { bubbles: true, cancelable: true }),
        );
        await new Promise((resolve) => setTimeout(resolve, 15));
        data = new dom.window.FormData(form);
        assert.equal(
            data.get("tests[]"),
            "1*null*null",
            "Submitting must not disable and omit form fields",
        );
        assert.ok(data.get("_token"));
    }
    if (page.screen === "barcode") {
        const label = dom.window.document.querySelector(".barcode-label");
        assert.ok(label, "barcode page: missing thermal tube label");
        assert.ok(
            label.querySelector(".tube-barcode svg"),
            "barcode page: missing scannable SVG barcode",
        );
        assert.ok(
            label.textContent.includes(
                `LAB-${String(page.record.id).padStart(6, "0")}`,
            ),
            "barcode page: missing accession number",
        );
        assert.ok(
            label.textContent.includes(page.record.patient.firstname),
            "barcode page: missing patient identity",
        );
        assert.equal(
            dom.window.document.querySelector(".labels").classList.contains(
                "labels-50x25",
            ),
            true,
            "barcode page: thermal 50x25 format must be the default",
        );
    }
    dom.window.close();
    count++;
}
console.log(
    `${count} React pages rendered; order selection and form submission verified.`,
);
